static void test_ev_mode_init_restores_defaults_after_dirty_state(void)
{
    EV_MODE_DATA_BLOCK_s *db;
    TIME_t t;

    ev_mode_init();
    ev_mode_cfg();
    db = ev_mode_get();
    db->airbag_sig_status = FALSE;
    db->ig_state = TRUE;
    db->bms_ready_to_work = TRUE;
    db->dcdc_start_ready = TRUE;
    db->dcu_start_ready = TRUE;
    db->bms_soc = 50.0f;
    db->mode = ev_mode_ready;
    db->mode_state = ev_state_ready_s;
    db->drive_ready = TRUE;
    db->fault_soc_low_flg = TRUE;
    db->cnt_pcharge_vol_incompatible_fault = 2U;
    db->ready_contactor_timeout = 10U;
    db->percharge_timeout = 20U;
    t.sec = 1U;
    t.up_time_ms = 1U;
    (void)ev_mode_management(t, db);

    ev_mode_init();
    db = ev_mode_get();

    TEST_ASSERT_EQUAL_UINT32(MAX_uint32_t, db->timestamp);
    TEST_ASSERT_EQUAL_UINT32(MAX_uint32_t, db->previous_timestamp);
    TEST_ASSERT_EQUAL_UINT32(MAX_uint32_t, db->ready_contactor_timeout);
    TEST_ASSERT_EQUAL_UINT32(MAX_uint32_t, db->ready_pluggin_timeout);
    TEST_ASSERT_EQUAL_UINT32(MAX_uint32_t, db->change_over_contactor_timeout);
    TEST_ASSERT_EQUAL_UINT32(MAX_uint32_t, db->change_over_overcurrent_timeout);
    TEST_ASSERT_EQUAL_UINT32(MAX_uint32_t, db->change_dactive_timeout);
    TEST_ASSERT_EQUAL_UINT32(MAX_uint32_t, db->percharge_timeout);
    TEST_ASSERT_FALSE(db->ndr_state_d);
    TEST_ASSERT_FALSE(db->slow_charger_pluggin);
    TEST_ASSERT_FALSE(db->start_state);
    TEST_ASSERT_FALSE(db->ig_state);
    TEST_ASSERT_FALSE(db->bms_ready_to_work);
    TEST_ASSERT_FALSE(db->drive_ready);
    TEST_ASSERT_EQUAL(ev_mode_off, db->mode);
    TEST_ASSERT_EQUAL(ev_mode_off, db->previouse_mode);
    TEST_ASSERT_EQUAL(ev_state_off_s, db->mode_state);
    TEST_ASSERT_EQUAL_FLOAT(MAX_float32_t, db->bms_soc);
    TEST_ASSERT_EQUAL_UINT16(MAX_uint16_t, db->cnt_pcharge_vol_incompatible_fault);
    TEST_ASSERT_FALSE(db->fault_soc_low_flg);
    TEST_ASSERT_FALSE(db->charge_deactive);
    TEST_ASSERT_FALSE(db->precharge_cont_open);
}

