/* 5.5 OFF Mode (ev_mode_off_mode()) */

static void test_ev_mode_off_mode_returns_false_when_any_fault_flag_set(void)
{
    EV_MODE_DATA_BLOCK_s *db;
    TIME_t t;
    boolean_t result;
    uint16_t i;

    for (i = 0U; i < 15U; i++)
    {
        ev_mode_init();
        ev_mode_cfg();
        db = ev_mode_get();
        db->airbag_sig_status = FALSE;
        db->ig_state = TRUE;
        db->bms_ready_to_work = TRUE;
        db->dcdc_start_ready = TRUE;
        db->dcu_start_ready = TRUE;
        db->mode_state = ev_state_off_s;
        if (i == 0U) { db->fault_soc_low_flg = TRUE; }
        else if (i == 1U) { db->fault_soc_high_flg = TRUE; }
        else if (i == 2U) { db->fualt_ndr_not_pn_flg = TRUE; }
        else if (i == 3U) { db->fault_pcharge_vol_incompatible_flg = TRUE; }
        else if (i == 4U) { db->fault_pcharge_timeout_flg = TRUE; }
        else if (i == 5U) { db->fault_key_in_start_state_flg = TRUE; }
        else if (i == 6U) { db->fault_emergency_stop_flg = TRUE; }
        else if (i == 7U) { db->fault_plugging_flg = TRUE; }
        else if (i == 8U) { db->fault_contactor_status_flg = TRUE; }
        else if (i == 9U) { db->fault_bms_not_ready_flg = TRUE; }
        else if (i == 10U) { db->fault_dcu_not_ready_flg = TRUE; }
        else if (i == 11U) { db->fault_dcdc_not_ready_flg = TRUE; }
        else if (i == 12U) { db->fault_charge_deactive_flg = TRUE; }
        else if (i == 13U) { db->fault_airbag_flg = TRUE; }
        else { db->fault_hv_open_flg = TRUE; }
        t.sec = 0U;
        t.up_time_ms = 0U;
        result = ev_mode_management(t, db);
        /* BMS/DCU/DCDC not-ready flags are force-cleared just before the AND. */
        if ((i == 9U) || (i == 10U) || (i == 11U))
        {
            TEST_ASSERT_TRUE(result);
            TEST_ASSERT_EQUAL(ev_state_precharge_s, db->mode_state);
        }
        else
        {
            TEST_ASSERT_FALSE(result);
            TEST_ASSERT_EQUAL(ev_mode_off, db->mode);
            TEST_ASSERT_EQUAL(ev_state_off_s, db->mode_state);
        }
    }
}

