/* 5.11 Repeated-Call / Overwrite Behavior (Cross-Cutting) */

static void test_ev_mode_management_reaches_ready_through_full_happy_path_sequence(void)
{
    EV_MODE_DATA_BLOCK_s *db;
    TIME_t t;

    ev_mode_init();
    ev_mode_cfg();
    db = ev_mode_get();
    db->airbag_sig_status = FALSE;
    db->ig_state = TRUE;
    db->hv_open_status = FALSE;
    db->bms_ready_to_work = TRUE;
    db->dcdc_start_ready = TRUE;
    db->dcu_start_ready = TRUE;
    db->bms_soc = 50.0f;
    db->drive_ready_permission = TRUE;
    db->dcdc_ready_to_work = TRUE;
    db->precharge_cont_open = FALSE;
    db->positive_cont_open = FALSE;
    db->negative_cont_open = FALSE;
    db->bms_pack_volatge = 400.0f;
    db->drive_voltage = 405.0f;
    db->mode_state = ev_state_off_s;
    t.sec = 0U;
    t.up_time_ms = 0U;
    (void)ev_mode_management(t, db);
    TEST_ASSERT_EQUAL(ev_state_precharge_s, db->mode_state);
    (void)ev_mode_management(t, db);
    TEST_ASSERT_EQUAL(ev_state_change_over_s, db->mode_state);
    (void)ev_mode_management(t, db);
    t.sec = 1U;
    (void)ev_mode_management(t, db);
    TEST_ASSERT_EQUAL(ev_state_ready_s, db->mode_state);
    db->precharge_cont_open = TRUE;
    (void)ev_mode_management(t, db);
    TEST_ASSERT_EQUAL(ev_state_ready_s, db->mode_state);
    TEST_ASSERT_EQUAL(ev_mode_ready, db->mode);
    TEST_ASSERT_TRUE(db->drive_ready);
}

static void test_ev_mode_management_requires_full_reentry_after_bms_drop_in_ready(void)
{
    EV_MODE_DATA_BLOCK_s *db;
    TIME_t t;

    ev_mode_init();
    ev_mode_cfg();
    db = ev_mode_get();
    db->ig_state = TRUE;
    db->airbag_sig_status = FALSE;
    db->bms_ready_to_work = TRUE;
    db->dcu_start_ready = TRUE;
    db->precharge_cont_open = TRUE;
    db->positive_cont_open = FALSE;
    db->negative_cont_open = FALSE;
    db->dcdc_ready_to_work = TRUE;
    db->bms_soc = 50.0f;
    db->drive_ready_permission = TRUE;
    db->slow_charger_pluggin = FALSE;
    db->fast_charger_pluggin = FALSE;
    db->mode_state = ev_state_ready_s;
    t.sec = 0U;
    t.up_time_ms = 0U;
    (void)ev_mode_management(t, db);
    TEST_ASSERT_EQUAL(ev_state_ready_s, db->mode_state);
    TEST_ASSERT_TRUE(db->drive_ready);
    db->bms_ready_to_work = FALSE;
    (void)ev_mode_management(t, db);
    TEST_ASSERT_EQUAL(ev_mode_off, db->mode);
    TEST_ASSERT_FALSE(db->drive_ready);
    TEST_ASSERT_EQUAL(ev_state_off_s, db->mode_state);
    db->bms_ready_to_work = TRUE;
    db->dcdc_start_ready = TRUE;
    (void)ev_mode_management(t, db);
    TEST_ASSERT_EQUAL(ev_state_precharge_s, db->mode_state);
    TEST_ASSERT_TRUE(db->mode_state != ev_state_ready_s);
}

